values
('bmlt-lab-management-safety-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',2300,$json${"question":"The primary purpose of a laboratory standard operating procedure (SOP) is to:","translation":"","options":["Provide standardized written instructions","Replace staff training","Eliminate quality control","Record patient diagnosis only"],"correctIndex":0,"explanation":"SOPs standardize processes and reduce variation between operators.","explanationNe":"SOP ले काम गर्ने प्रक्रिया एकरूप बनाउँछ र त्रुटि घटाउँछ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2301,$json${"question":"An SOP should be reviewed:","translation":"","options":["Periodically and whenever procedures change","Only when an inspector visits","Never after approval","Only after an accident"],"correctIndex":0,"explanation":"Scheduled review keeps procedures current and aligned with validated practice.","explanationNe":"SOP नियमित रूपमा र प्रक्रिया परिवर्तन हुँदा समीक्षा गर्नुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',2302,$json${"question":"The person responsible for authorizing a laboratory result should be:","translation":"","options":["A qualified and authorized professional","Any visitor","A patient attendant","An untrained cleaner"],"correctIndex":0,"explanation":"Result authorization must follow professional competency and institutional policy.","explanationNe":"Report स्वीकृत गर्ने व्यक्ति योग्य र अधिकारप्राप्त हुनुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',2303,$json${"question":"A laboratory incident should be:","translation":"","options":["Reported, documented and investigated","Hidden to protect reputation","Deleted from records","Discussed only informally"],"correctIndex":0,"explanation":"Incident reporting supports corrective action and patient safety.","explanationNe":"Incident report र अनुसन्धानले सुधार तथा बिरामी सुरक्षा बढाउँछ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',2304,$json${"question":"The first action after a needle-stick injury is generally to:","translation":"","options":["Wash the area with soap and water promptly","Squeeze aggressively for several minutes","Apply bleach","Ignore it if there is no pain"],"correctIndex":0,"explanation":"Immediate washing followed by prompt occupational health assessment is recommended.","explanationNe":"सुईले घोचेपछि साबुनपानीले तुरुन्त धुने र स्वास्थ्य मूल्याङ्कन गराउने।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',2305,$json${"question":"Used needles should be discarded:","translation":"","options":["Immediately into an approved sharps container","In ordinary waste","After recapping","Into a sink"],"correctIndex":0,"explanation":"Sharps containers reduce needlestick injuries and must be puncture-resistant.","explanationNe":"प्रयोग भएका सुई तुरुन्त puncture-resistant sharps container मा हाल्नुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',2306,$json${"question":"Routine recapping of used needles is:","translation":"","options":["Avoided","Mandatory","Safer than disposal","Required before transport"],"correctIndex":0,"explanation":"Recapping increases needlestick risk and should be avoided; exceptions require a safe one-handed method.","explanationNe":"प्रयोग भएको सुई पुनः cap गर्दा चोटको जोखिम बढ्छ, त्यसैले नगर्नुहोस्।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',2307,$json${"question":"The best way to prevent laboratory-acquired infection is:","translation":"","options":["Risk-based biosafety practices and standard precautions","Taste-testing specimens","Working without PPE","Keeping cultures open"],"correctIndex":0,"explanation":"Standard precautions, training, containment and safe procedures reduce exposure risk.","explanationNe":"Standard precaution, तालिम र सुरक्षित प्रक्रिया संक्रमण रोक्न महत्त्वपूर्ण छन्।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',2308,$json${"question":"A biological safety cabinet is primarily used to:","translation":"","options":["Contain infectious aerosols during specified procedures","Sterilize all glassware","Replace hand hygiene","Store chemicals permanently"],"correctIndex":0,"explanation":"A suitable certified biological safety cabinet provides containment for procedures that may generate infectious aerosols.","explanationNe":"उपयुक्त biological safety cabinet ले infectious aerosol नियन्त्रण गर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',2309,$json${"question":"A chemical fume hood is designed mainly to:","translation":"","options":["Remove hazardous chemical vapours","Protect cultures from contamination","Incubate bacteria","Measure pH"],"correctIndex":0,"explanation":"Fume hoods protect users from hazardous chemical vapours and gases.","explanationNe":"Fume hood ले हानिकारक chemical vapour बाहिर निकाल्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',2310,$json${"question":"Autoclaving sterilizes by using:","translation":"","options":["Saturated steam under pressure","Dry cold air","Ultraviolet light only","Alcohol vapour"],"correctIndex":0,"explanation":"Autoclaves use moist heat under pressure for sterilization.","explanationNe":"Autoclave ले pressure सहितको saturated steam प्रयोग गर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',2311,$json${"question":"A common autoclave cycle for wrapped instruments is approximately:","translation":"","options":["121°C at 15 psi for a validated holding time","60°C at 1 psi","100°C without pressure for 1 minute","200°C in water"],"correctIndex":0,"explanation":"A commonly used cycle is 121°C at about 15 psi, with exposure time validated for the load.","explanationNe":"सामान्य cycle १२१°C र करिब १५ psi हो; समय load अनुसार validate गरिन्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',2312,$json${"question":"A chemical indicator strip in an autoclave load shows:","translation":"","options":["Exposure to specified process conditions","Guaranteed sterility of every item","Absence of all spores","Correct patient identity"],"correctIndex":0,"explanation":"Chemical indicators show exposure to one or more sterilization parameters but do not alone prove sterility.","explanationNe":"Chemical indicator ले प्रक्रिया condition पुगेको संकेत गर्छ, sterility पूर्ण प्रमाणित गर्दैन।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',2313,$json${"question":"A biological indicator for steam sterilization commonly contains spores of:","translation":"","options":["Geobacillus stearothermophilus","Escherichia coli","Staphylococcus aureus","Candida albicans"],"correctIndex":0,"explanation":"Resistant Geobacillus stearothermophilus spores are used to monitor steam sterilization efficacy.","explanationNe":"Steam sterilization जाँच्न Geobacillus stearothermophilus का spore प्रयोग हुन्छन्।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',2314,$json${"question":"Laboratory chemical waste should be:","translation":"","options":["Segregated and disposed of according to safety rules","Mixed with all general waste","Poured into any drain","Stored in food containers"],"correctIndex":0,"explanation":"Chemical waste requires segregation, compatible containers, labelling and approved disposal.","explanationNe":"Chemical waste छुट्याएर label सहित सुरक्षित तरिकाले व्यवस्थापन गर्नुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',2315,$json${"question":"A Safety Data Sheet (SDS) provides information about:","translation":"","options":["Chemical hazards, handling and emergency measures","Patient blood group","Instrument calibration results only","Staff attendance"],"correctIndex":0,"explanation":"SDS describes hazards, safe handling, storage, exposure control and first aid.","explanationNe":"SDS मा chemical को जोखिम, handling, storage र first aid जानकारी हुन्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',2316,$json${"question":"The correct response to a chemical splash in the eyes is to:","translation":"","options":["Use the eyewash station immediately and seek assessment","Rub the eyes","Neutralize with another chemical","Wait until the end of shift"],"correctIndex":0,"explanation":"Immediate prolonged irrigation and prompt medical assessment are essential.","explanationNe":"आँखामा chemical परे तुरुन्त eyewash ले धुने र स्वास्थ्य जाँच गराउने।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
