('bmlt-lab-management-safety-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',2319,$json${"question":"Patient laboratory information should be shared:","translation":"","options":["Only with authorized persons for legitimate purposes","On public social media","With any caller","On an open notice board"],"correctIndex":0,"explanation":"Confidentiality requires limiting access to authorized purposes and personnel.","explanationNe":"बिरामीको जानकारी अधिकारप्राप्त व्यक्तिसँग आवश्यक प्रयोजनका लागि मात्र साझा गर्नुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
