('bmlt-lab-management-safety-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',2322,$json${"question":"The purpose of inventory control is to:","translation":"","options":["Maintain adequate supplies and prevent expiry or stock-outs","Increase unnecessary purchasing","Avoid recording stock","Store all reagents together"],"correctIndex":0,"explanation":"Inventory systems monitor quantities, lot numbers, expiry dates and reorder levels.","explanationNe":"Inventory control ले stock, lot number र expiry व्यवस्थापन गर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
