('bmlt-lab-management-safety-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2301,$json${"question":"Equipment maintenance records should document:","translation":"","options":["Service, repairs, calibration and performance checks","Only purchase price","Patient diagnoses","Staff leave"],"correctIndex":0,"explanation":"Maintenance documentation demonstrates equipment reliability and traceability.","explanationNe":"Maintenance record मा service, repair, calibration र performance जाँच लेखिन्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
