('bmlt-lab-management-safety-mock-004','BMLT','BMLT NHPC Licensing','mock','free',2303,$json${"question":"A competency assessment evaluates whether staff can:","translation":"","options":["Perform assigned tasks correctly and safely","Memorize the manager's phone number","Work without procedures","Avoid all documentation"],"correctIndex":0,"explanation":"Competency assessment verifies practical knowledge, skills and safe performance.","explanationNe":"Competency assessment ले कर्मचारीको ज्ञान, सीप र सुरक्षित काम गर्ने क्षमता जाँच्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
('bmlt-lab-management-safety-mock-005','BMLT','BMLT NHPC Licensing','mock','free',2304,$json${"question":"A corrective action is intended to:","translation":"","options":["Address the cause of a detected nonconformity","Hide the error","Punish every staff member","Delete the result"],"correctIndex":0,"explanation":"Corrective action addresses the cause to prevent recurrence.","explanationNe":"Corrective action ले त्रुटिको मूल कारण हटाएर पुनः हुन नदिन खोज्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
