('bmlt-lab-management-safety-mock-007','BMLT','BMLT NHPC Licensing','mock','free',2306,$json${"question":"A root cause analysis seeks to identify:","translation":"","options":["Underlying system causes of an event","Only the person to blame","The fastest way to close a report","Patient's occupation"],"correctIndex":0,"explanation":"Root cause analysis examines contributing system factors rather than stopping at blame.","explanationNe":"Root cause analysis ले दोष मात्र नभई प्रणालीगत मूल कारण खोज्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
