('bmlt-lab-management-safety-mock-010','BMLT','BMLT NHPC Licensing','mock','free',2309,$json${"question":"An internal audit should be:","translation":"","options":["Systematic, documented and based on defined criteria","Random gossip","A substitute for staff training","Done without records"],"correctIndex":0,"explanation":"A planned audit uses criteria, evidence, findings and follow-up.","explanationNe":"Internal audit योजना, प्रमाण, निष्कर्ष र follow-up सहित हुनुपर्छ।","topic":"Laboratory Management, Safety and Professional Practice"}$json$::jsonb,true),
